def solve(grid_in):
    import copy
    grid = copy.deepcopy(grid_in)
    h, w = len(grid), len(grid[0])

    def find_all_frames():
        """Find all rectangular frames made of 2s"""
        frames = []
        seen = set()

        for r in range(h):
            for c in range(w):
                if grid[r][c] != 2:
                    continue
                key = (r, c)
                if key in seen:
                    continue
                seen.add(key)

                # This could be part of a frame - try to complete it
                # Expand horizontally to find right boundary
                left, top, right = c, r, c
                # Expand vertically to find bottom
                bottom = r

                # Check if we have a top row segment
                top_segment = []
                tc = r
                while tc < h and grid[tc][c] == 2:
                    top_segment.append(tc)
                    tc += 1
                if not top_segment:
                    continue

                tr, left = top_segment[-1], c
                # Expand left
                lc, rc = left, left
                while lc >= 0 and grid[tr][lc] == 2:
                    lc -= 1
                if lc < 0:
                    continue
                left = lc + 1
                rc = left + 100
                while rc < w and grid[tr][rc] == 2:
                    rc += 1
                if rc > w:
                    rc = w - 1

                # Try to expand downward from leftmost point
                temp_bottom = tr
                while temp_bottom < h:
                    valid = True
                    for cc in range(left, rc + 1):
                        if grid[temp_bottom][cc] != 2:
                            valid = False
                            break
                    if valid:
                        temp_bottom += 1
                    else:
                        break

                if temp_bottom > tr + 1:
                    frames.append({'top': tr, 'left': left, 'bottom': temp_bottom - 1, 'right': rc})

        return frames

    frames = find_all_frames()
    print(f"Found {len(frames)} frames")
    for i, f in enumerate(frames):
        print(f"Frame {i}: {f}")

    # Fill interior of each frame
    result = []
    for r in range(h):
        row = []
        for c in range(w):
            val = grid[r][c]
            for f in frames:
                if f['top'] <= r <= f['bottom'] and f['left'] <= c <= f['right']:
                    # Interior (not border)
                    if r != f['top'] and r != f['bottom'] and c != f['left'] and c != f['right']:
                        row.append(8)
                    else:
                        row.append(val)
                else:
                    row.append(val)
        result.append(row)

    return result

